entries[423831] = { ["name"] = "Khadgars juckende Verwandlung", ["text"] = "30 Meter Reichweite\nSofort\nVerwandelt den Gegner in ein Schaf, das bis Abbruch lang handlungsunfähig umherirrt. In diesem Zustand kann das Opfer nicht agieren, regeneriert aber seine Gesundheit sehr schnell. Schaden beendet den Effekt. Es kann nur jeweils 1 Ziel betroffen sein.\n\nWirkt nur bei Tieren, Humanoiden und Kleintieren.\n\nKann Juckreiz auslösen." }
entries[423834] = { ["name"] = "Qualmendes Ersticken", ["text"] = "3 Meter Reichweite\nSofort\nErstickt einen Spielercharakter, wodurch dieser 30 Sek. lang 100% weniger Heilung erhält und alle 1 Sek. 145047 Feuerschaden erleidet.\n\nDieser Effekt entzieht zusätzlich Verbündeten innerhalb von 6 Metern alle 1 Sek. 58011 Gesundheit." }
