entries[423839] = { ["name"] = "Rache des Sturms", ["text"] = "Sofort\nDer Sturmhammer von Sturmreiter Vokmar schwächt die Leerensteinmonstrosität, wodurch diese betäubt wird und 20 Sek. lang 100% mehr Schaden erleidet." }
entries[423840] = { ["name"] = "Bindende Wurzeln des Erzdruiden", ["text"] = "35 Meter Reichweite\nWirken in 0.5 sek.\nHält das Ziel bis Abbruch lang an Ort und Stelle fest. Schaden kann den Effekt unterbrechen." }
entries[423842] = { ["name"] = "Tiefgrünes Verwunden", ["text"] = "200 Meter Reichweite\nSofort 1 sek. Abklingzeit\nBeim Kreuzen der Fäden von ' Grüne Matrix ' zerstreut der Kreiswächter Lebensenergie, was allen Spielercharakteren 2175710 Naturschaden zufügt. Dieser Effekt wird mit jedem Kreuzen um 100% verstärkt." }
entries[423846] = { ["name"] = "Woge des Wahnsinns", ["text"] = "Sofort\nNach 2 Einsätzen von 'Verschlingende Seuche' wird Euer nächster Einsatz von 'Gedankenschinden' in einen mächtigeren Zauber verwandelt. Kann bis zu 4 Aufladungen ansammeln.\n\nGedankenschinden: Wahnsinn\nGreift die Gedanken des Ziels mit Schattenenergie an, fügt ihm so im Verlauf von 1.5 Sek. (598.868% der Zaubermacht) Schattenschaden zu und verringert seine Bewegungsgeschwindigkeit um 70%.\n\nErzeugt im Verlauf der Effektdauer 8 Wahnsinn." }
entries[423851] = { ["name"] = "Konstruktwucherung", ["text"] = "Animabonus\nUnbegrenzte Reichweite\nSofort\nErhöht Euren verursachten Schaden um 15% und Eure Größe um 20%. Dieser Effekt hält an, bis Eure Gesundheit unter 50% fällt." }
entries[423852] = { ["name"] = "Haselmaus Ecila", ["text"] = "Animabonus\nUnbegrenzte Reichweite\nSofort 1.5 sek. Abklingzeit\nErhöht das Tempo 1 Min. lang um 5%." }
