entries[424406] = { ["name"] = "Dornenruferklaue", ["text"] = "Ca. 1 Procs pro Minute\nEure Nahkampffähigkeiten haben eine Chance, das Ziel mit 'Dorngeist' zu belegen, was im Verlauf von 15 Sek. [Quellwert] Naturschaden verursacht. Wenn Ihr das Ziel trefft, während der Geist noch da ist, werden 265 Naturschaden verursacht, die auf alle Gegner in der Nähe aufgeteilt werden. Dieser Effekt kann nur alle 2 Sek. auftreten.\n\nWenn ein Ziel stirbt, während es mit 'Dorngeist' belegt ist, sucht sich der Geist einen neuen Gegner.", ["unresolvedValues"] = true }
