entries[424414] = { ["name"] = "Rüstung durchbohren", ["text"] = "40 Meter Reichweite\nWirken in 2.5 sek.\nHauptmann Talschrei schlitzt sein aktuelles Ziel, verursacht 9697798 körperlichen Schaden und lässt das Ziel bluten, wodurch es 7 Sek. lang alle 1 Sek. 1091002 körperlichen Schaden erleidet.\n\nDieser Effekt ist stapelbar." }
