entries[424419] = { ["name"] = "Schlachtruf", ["text"] = "50 Meter Reichweite\nWirken in 2.5 sek.\nHauptmann Talschrei entfesselt einen einschüchternden ' Schlachtruf ' und fügt allen Spielercharakteren 4364009 körperlichen Schaden zu. Ignoriert Rüstung.\n\nHauptmann Talschreis ' Schlachtruf ' inspiriert seine Verbündeten, gewährt jedem von ihnen 50 Energie und erhöht ihren verursachten Schaden 30 Sek. lang um 50%.\n\nDieser Effekt ist stapelbar." }
entries[424420] = { ["name"] = "Glutdetonation", ["text"] = "50 Meter Reichweite\nWirken in 4.5 sek.\nTaener Duelmal schleudert eine verheerende ' Glutdetonation ' auf einen Spielercharakter und fügt ihm 3879119 Feuerschaden zu. Das Opfer wird betäubt und erleidet 5 Sek. lang alle 1 Sek. 2424449 Feuerschaden." }
