entries[424428] = { ["name"] = "Eruption", ["text"] = "100 Meter Reichweite\nWirken in 2.5 sek.\nDas Wirken von 'Voraussicht' verbessert Eure nächste 'Eruption' mit schmaleren Rissen für jede aktive 'Voraussicht', die jeweils (110% der Zaubermacht) Schaden verursachen und 'Schwarzmacht' um 0.2 Sek verlängern." }
