entries[424454] = { ["name"] = "Blackout-Verstärkung", ["text"] = "Sofort\nKostenlose Einsätze von 'Wirbelnder Kranichtritt' gewähren 'Blackout-Verstärkung', sodass Euer nächster Einsatz von 'Blackout-Tritt' 250% mehr Schaden verursacht. Nahkampfangriffe haben eine Chance, 'Blackout-Verstärkung' zu gewähren." }
entries[424456] = { ["name"] = "Eingeweide zerschmettern", ["text"] = "300 Meter Reichweite\nSofort\nIgira springt zu Spielercharakteren, fügt Spielercharakteren innerhalb von 8 Metern um jeden Einschlagsort 652414 Schattenflammenschaden zu und stößt sie zurück. Igiras Sprünge fügen Spielercharakteren außerhalb der Einschlagszone 362619 Schattenflammenschaden zu." }
entries[424458] = { ["name"] = "Tollkühner Ansturm", ["text"] = "Unbegrenzte Reichweite\nSofort\nDer alte Wachsbart befiehlt Docht, auf den am weitesten entfernten Spielercharakter zuzustürmen. Dieser Angriff stößt alles in seinem Weg zurück, fügt allen Spielercharakteren 6061123 körperlichen Schaden zu und löst am Ende des Ansturms einen ' Einsturz ' aus.\n\nTödlich für Schuftknechte und Schuftmägde." }
