entries[424474] = { ["name"] = "Schattendämmertraumsäbler", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Ein Traumsäbler schlägt schnell aus den Schatten zu, schnappt sich kleinere Tiere und verschwindet dann wieder in der Dunkelheit, ohne dabei ein Geräusch zu machen. Die wenigen Glücklichen, die einen Traumsäbler beim Essen bestaunen konnten, haben dabei gesehen, wie sie vor dem Mahl noch genüsslich mit ihrer Beute spielen.\"\nErfolg:\nRuhm des Traumschlachtzüglers\nKategorie:\nDungeons & Schlachtzüge" }
entries[424475] = { ["name"] = "Erinnerung an Ursoc", ["text"] = "100 Meter Reichweite\nSofort\nStürmt auf das Ziel zu, rammt es und stößt es zurück." }
entries[424476] = { ["name"] = "Winternachttraumsäbler", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Diese nachtaktiven Traumsäbler tragen die Kälte des Winters in sich und schlafen oft tagelang, wenn sie nicht anderweitig geweckt werden.\"\nBeute von:\nTraumsaattruhe\nZone:\nSmaragdgrüner Traum" }
entries[424477] = { ["name"] = "Gewalttätige Flora", ["text"] = "100 Meter Reichweite\nWirken in 1 sek.\nNymue lässt 'Schwellendes Gewächs' aus dem Boden hervorbrechen, was allen Spielercharakteren 1 Min. lang alle 2 Sek. 15955 Naturschaden zufügt.\n\nSpielercharaktere, die auf einem Gewächs stehen, bremsen das Wachstum, was seine Dauer erheblich verkürzt." }
entries[424478] = { ["name"] = "Bewundererhinterhalt" }
entries[424479] = { ["name"] = "Abendsonnetraumsäbler", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Diese Traumsäbler sind wilde Kämpfer, wobei sie dennoch oft dabei gesehen werden können, wie sie faul und ausgestreckt auf offenem Feld liegen. Nach einem ausgelassenen Bad in der Wärme des Tageslichts, brennen ihre Flammen umso heller.\"\nVerkäufer:\nTalisa Flüsterblüte\nZone:\nSmaragdgrüner Traum\nKosten:\n1" }
entries[424481] = { ["name"] = "Schwellendes Gewächs", ["text"] = "300 Meter Reichweite\nSofort\nNymue lässt 'Schwellendes Gewächs' aus dem Boden hervorbrechen, was allen Spielercharakteren 1 Min. lang alle 2 Sek. 15955 Naturschaden zufügt.\n\nSpielercharaktere, die auf einem Gewächs stehen, bremsen das Wachstum, was seine Dauer erheblich verkürzt." }
entries[424482] = { ["name"] = "Morgenblütetraumsäbler", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Bekannt für die überschwängliche Energie, die von ihnen ausgeht, sind diese Säbler berüchtigte Trickser. Ihr Brüllen verscheucht die frühen Vögel, deren Gezwitscher sie weckt.\"\nVerkäufer:\nTalisa Flüsterblüte\nZone:\nSmaragdgrüner Traum\nKosten:\n1" }
