entries[424484] = { ["name"] = "Anu'relos, Wegweisung der Flamme", ["text"] = "Wirken in 1.5 sek.\nBeschwört Anu'relos, Wegweisung der Flamme, und gibt sie wieder frei.\n\nBei diesem Reittier kann 'Mitreiten' verwendet werden.\n\"Obwohl ihre Federn mit zerstörerischen Flammen bedeckt zu sein scheinen, verbrennen sie einen nicht, sondern geben lediglich eine angenehme Wärme ab.\"\nBeute von:\nFyrakk\nZone:\nAmirdrassil, Hoffnung des Traums (Mythisch)" }
