entries[424529] = { ["name"] = "Hochblumenlieferungen", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nErweckter Frost , Erweckte Luft\nDie Hochblume ist eine übliche Basisreagenz für viele Tränke und Phiolen. Wir brauchen 100 Stück davon und einige erweckte Elemente, wenn Ihr welche übrig habt.\n\nIhr erhaltet 1 Warenlieferung, die Ihr wöchentlich bei Eran'nda abgeben könnt, um die Traumwächter zu unterstützen." }
