entries[424534] = { ["name"] = "Boshafte Mondbestie", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Anders als andere seiner Art hat diese Mondbestie Geschmack an Hordenblut gefunden und eine Vorliebe für die Farbe Blau entwickelt.\"\nPvP:\nDragonflight: Saison 3\nSaisonbelohnung für gewertete Arena und gewertete Schlachtfelder" }
entries[424535] = { ["name"] = "Boshafte Mondbestie", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Anders als andere seiner Art hat diese Mondbestie Geschmack an Allianzblut gefunden und eine Vorliebe für die Farbe Rot entwickelt.\"\nPvP:\nDragonflight: Saison 3\nSaisonbelohnung für gewertete Arena und gewertete Schlachtfelder" }
entries[424538] = { ["name"] = "Ungewöhnliche Kräuterlieferungen", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nErweckter Frost , Erweckte Luft\nDie Kräuter der Dracheninseln können uns auf unterschiedlichste Weise in Form von Tränken und Phiolen nützlich werden. Bringt uns bitte 25 beliebige Kräuter und eine kleine Menge erweckter Elemente.\n\nIhr erhaltet 1 Warenlieferung, die Ihr wöchentlich bei Eran'nda abgeben könnt, um die Traumwächter zu unterstützen." }
entries[424539] = { ["name"] = "Drache des drakonischen Gladiators", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Seine Schwingen verdunkeln den Himmel mit dem Schatten der Eroberung.\"\nErfolg:\nGladiator: Saison 4 von Dragonflight\nKategorie:\nSpieler gegen Spieler" }
