entries[424556] = { ["name"] = "Mordlust", ["text"] = "10 Meter Reichweite\nSofort\nFinishing-Move, der eine Schusssalve entfesselt und zufällige Gegner innerhalb von 8 Metern trifft und ihnen körperlichen Schaden zuzufügt. Die Anzahl an Treffern wird pro Combopunkt erhöht.\n\nStellt alle 0.50 Sek. 1 Combopunkt wieder her.\n\n1 Punkt: [((225% der Angriffskraft) + (225% der Angriffskraft)) * 2] im Laufe von 0.50 Sek.\n2 Punkte: [((225% der Angriffskraft) + (225% der Angriffskraft)) * 3] im Laufe von 1.00 Sek.\n3 Punkte: [((225% der Angriffskraft) + (225% der Angriffskraft)) * 4] im Laufe von 1.50 Sek.\n4 Punkte: [((225% der Angriffskraft) + (225% der Angriffskraft)) * 5] im Laufe von 2.00 Sek.\n5 Punkte: [((225% der Angriffskraft) + (225% der Angriffskraft)) * 6] im Laufe von 2.50 Sek.\n[ 6 Punkte: [((225% der Angriffskraft) + (225% der Angriffskraft)) * 7] im Laufe von 3.00 Sek.] [ 7 Punkte: [((225% der Angriffskraft) + (225% der Angriffskraft)) * 8] im Laufe von 3.50 Sek.]" }
entries[424557] = { ["name"] = "Unbändigkeit", ["text"] = "Der Schaden von 'Tötungsbefehl' ist um 10% erhöht. 'Stachelpfeil' hält 2.0 Sek. länger an." }
entries[424558] = { ["name"] = "Meistertreiber", ["text"] = "Jedes Mal, wenn 'Stachelpfeil' Schaden verursacht, wird die Abklingzeit von 'Tötungsbefehl' um 0.50 Sek. verringert." }
