entries[424562] = { ["name"] = "Mordlust", ["text"] = "Sofort\nFinishing-Move, der eine Schusssalve entfesselt und zufällige Gegner innerhalb von 8 Metern trifft und ihnen körperlichen Schaden zuzufügt. Die Anzahl an Treffern wird pro Combopunkt erhöht.\n\nStellt alle 0.50 Sek. 1 Combopunkt wieder her.\n\n1 Punkt: [((225% der Angriffskraft) + (225% der Angriffskraft)) * 2] im Laufe von 0.50 Sek.\n2 Punkte: [((225% der Angriffskraft) + (225% der Angriffskraft)) * 3] im Laufe von 1.00 Sek.\n3 Punkte: [((225% der Angriffskraft) + (225% der Angriffskraft)) * 4] im Laufe von 1.50 Sek.\n4 Punkte: [((225% der Angriffskraft) + (225% der Angriffskraft)) * 5] im Laufe von 2.00 Sek.\n5 Punkte: [((225% der Angriffskraft) + (225% der Angriffskraft)) * 6] im Laufe von 2.50 Sek.\n[ 6 Punkte: [((225% der Angriffskraft) + (225% der Angriffskraft)) * 7] im Laufe von 3.00 Sek.] [ 7 Punkte: [((225% der Angriffskraft) + (225% der Angriffskraft)) * 8] im Laufe von 3.50 Sek.]" }
entries[424564] = { ["name"] = "Mordlust", ["text"] = "Sofort\nFinishing-Move, der eine Schusssalve entfesselt und zufällige Gegner innerhalb von 8 Metern trifft und ihnen körperlichen Schaden zuzufügt. Die Anzahl an Treffern wird pro Combopunkt erhöht.\n\nStellt alle 0.50 Sek. 1 Combopunkt wieder her.\n\n1 Punkt: [((225% der Angriffskraft) + (225% der Angriffskraft)) * 2] im Laufe von 0.50 Sek.\n2 Punkte: [((225% der Angriffskraft) + (225% der Angriffskraft)) * 3] im Laufe von 1.00 Sek.\n3 Punkte: [((225% der Angriffskraft) + (225% der Angriffskraft)) * 4] im Laufe von 1.50 Sek.\n4 Punkte: [((225% der Angriffskraft) + (225% der Angriffskraft)) * 5] im Laufe von 2.00 Sek.\n5 Punkte: [((225% der Angriffskraft) + (225% der Angriffskraft)) * 6] im Laufe von 2.50 Sek.\n[ 6 Punkte: [((225% der Angriffskraft) + (225% der Angriffskraft)) * 7] im Laufe von 3.00 Sek.] [ 7 Punkte: [((225% der Angriffskraft) + (225% der Angriffskraft)) * 8] im Laufe von 3.50 Sek.]" }
entries[424565] = { ["name"] = "Explosive Eichel", ["text"] = "50 Meter Reichweite\nWirken in 1.4 sek. 30 sek. Abklingzeit\nWirft eine Eichel, verursacht 41 körperlichen Schaden und stößt Ziele zurück." }
entries[424566] = { ["name"] = "Eichel werfen", ["text"] = "100 Meter Reichweite\nSofort\nWirft eine Eichel, verursacht 41 körperlichen Schaden und stößt Ziele zurück." }
entries[424567] = { ["name"] = "Wilde Instinkte", ["text"] = "100 Meter Reichweite\nSofort\nSolange 'Ruf der Wildnis' aktiv ist, erleidet das Ziel Eures 'Tötungsbefehls' bei jedem Einsatz von 'Tötungsbefehl' um 3% erhöhten Schaden durch all Eure Begleiter, bis zu 10-mal stapelbar." }
entries[424568] = { ["name"] = "Korb mit explosiven Eicheln", ["text"] = "Animabonus\n20 Meter Reichweite\nSofort 1 min Abklingzeit\nGewährt die Fähigkeit, Eicheln zu werfen, die beim Einschlag explodieren, Gegnern 41 Schaden zufügen und sie zurückstoßen." }
entries[424571] = { ["name"] = "Führung der Windläufer", ["text"] = "Sofort\nJeder abgefeuerte 'Windpfeil' verringert die Abklingzeit von 'Schnellfeuer' um 0.5,1 Sek., und pro 8 abgefeuerte 'Windpfeile' erhöht sich die Dauer Eures nächsten 'Volltreffers' um 1,1 Sek, bis zu einem Maximum von 10,1 Sek." }
entries[424572] = { ["name"] = "Paladin Retribution 10.2 Class Set 4pc", ["text"] = "'Zornerfüllte Sanktion' gewährt Euch 'Echos des Zorns', wodurch Euer nächster Einsatz von 'Urteil des Templers' oder 'Göttlicher Sturm' ein zweites Mal mit 25% Effektivität Schaden verursacht. Dieser Effekt verbraucht kein 'Richturteil'." }
entries[424576] = { ["name"] = "Lodernder Pilz" }
entries[424577] = { ["name"] = "Lodernder Pilz", ["text"] = "Unbegrenzte Reichweite\nSofort\nTindral lässt 9 Sek. lang alle 3 Sek. lodernde Pilze um sich herum entstehen. Jeder Pilz bricht nach 3 Sek. aus und fügt Spielercharakteren im Bereich 1087717 körperlichen Schaden sowie 434183 Feuerschaden zu und erhöht ihren durch lodernde Pilze erlittenen Schaden 3 Sek. lang um 500%.\n\nWenn ' Lodernder Pilz ' keinen Spielercharakter trifft, erleiden alle Spielercharaktere 506547 Feuerschaden." }
entries[424578] = { ["name"] = "Lodernder Pilz", ["text"] = "Unbegrenzte Reichweite\nSofort\nTindral lässt 9 Sek. lang alle 3 Sek. lodernde Pilze um sich herum entstehen. Jeder Pilz bricht nach 3 Sek. aus und fügt Spielercharakteren im Bereich 1087717 körperlichen Schaden sowie 434183 Feuerschaden zu und erhöht ihren durch lodernde Pilze erlittenen Schaden 3 Sek. lang um 500%.\n\nWenn ' Lodernder Pilz ' keinen Spielercharakter trifft, erleiden alle Spielercharaktere 506547 Feuerschaden." }
entries[424579] = { ["name"] = "Unterdrückende Glut", ["text"] = "Unbegrenzte Reichweite\nSofort\nTindral umgibt zufällige Spielercharaktere mit unterdrückender Glut und absorbiert die nächsten 261704 Heilung. Dieser Effekt ist stapelbar." }
entries[424580] = { ["name"] = "Sternschnuppe", ["text"] = "Unbegrenzte Reichweite\nSofort\nTindral lässt eine Sternschnuppe auf die Plattform stürzen, was allen Spielercharakteren 398880 Astralschaden zufügt und ' Sternfragmente ' zurücklässt." }
entries[424581] = { ["name"] = "Feuriges Wachstum", ["text"] = "Unbegrenzte Reichweite\nWirken in 1 sek.\nTindral lässt Flammen im Inneren zufälliger Spielercharaktere anwachsen, die diesen 20 Sek. lang alle 1 Sek. 87028 Feuerschaden zufügen.\n\nDie Flammen brechen aus Spielercharakteren aus, wenn 'Feuriges Wachstum' entfernt wird, die Spielercharaktere mit ' Haftende Asche ' belegen und an der Position des aktuellen Spielercharakters einen Bereich von ' Sengender Boden ' hinterlassen." }
entries[424582] = { ["name"] = "Haftende Asche", ["text"] = "Unbegrenzte Reichweite\nSofort\nDie Asche der Explosion von ' Feuriges Wachstum ' bleibt an allen Spielercharakteren haften und verursacht 2 Sek. lang alle 1 Sek. 14505 Feuerschaden. Dieser Effekt ist stapelbar.\n\nJeder zusätzliche Stapel von ' Haftende Asche ' erhöht den Schaden um 5000%." }
entries[424584] = { ["name"] = "Rasende Peitsche", ["text"] = "100 Meter Reichweite\nSofort\nInflicts 0 Frost damage to all enemies within 10 yards of the caster every 1 sec for 10 Sek.." }
entries[424585] = { ["name"] = "Rasender Flunker" }
entries[424586] = { ["name"] = "Suppe verteilen", ["text"] = "Nahkampfreichweite\nWirken in 1 sek.\nTragt einen Topf mit Tinooks Suppe. Bringt sie zu den Geistern von Iskaara, bevor sie kalt wird!" }
entries[424588] = { ["name"] = "Kleiner Mond", ["text"] = "100 Meter Reichweite\nSofort\n'Vollmond' ruft 2 kleine Monde herab, die (198.4% der Zaubermacht) Astralschaden verursachen und 3 Astrale Macht generieren." }
entries[424589] = { ["name"] = "Suppe essen", ["text"] = "Sofort\nMacht Pause! Sich die Zeit zum Essen zu nehmen, ist der Schlüssel zur Bewältigung harter Arbeit." }
entries[424590] = { ["name"] = "Zornerfüllte Sanktion", ["text"] = "Unbegrenzte Reichweite\nSofort\nVerurteilt einen ausgemerzten Gegner, was Eurem Ziel (100% der Angriffskraft) Heiligschaden und bis zu 4 Gegnern in der Nähe [(100% der Angriffskraft) / 2] Heiligschaden zufügt." }
entries[424591] = { ["name"] = "Suppe verteilen" }
entries[424594] = { ["name"] = "Wilde Wurzeln", ["text"] = "100 Meter Reichweite\nSofort\nHeals the caster for 1% of maximum health every 1 sec for 4 Sek.." }
entries[424595] = { ["name"] = "Angesengt", ["text"] = "Sofort\nDie umgebenden Feuer enthalten angesengten Efeu.\n\nKann mit ' Traumblüte ' eingedämmt werden." }
entries[424596] = { ["name"] = "Wilde Wurzeln", ["text"] = "10 Meter Reichweite\nWirken in 1.5 sek.\nCa. 6 Procs pro Minute\nAngriffe und Fähigkeiten erschaffen ab und zu einen Bereich des Wachstums, der den Zaubernden 4 Sek. lang alle 1 Sek. um 1% der maximalen Gesundheit heilt und gegnerische Ziele in der Nähe für 4 Sek. festwurzelt." }
entries[424597] = { ["name"] = "Verheerender Sturm", ["text"] = "100 Meter Reichweite\nSofort\nBenötigt Nahkampfwaffe\nEure Fähigkeiten 'Klingensturm', 'Verheerer' und 'Demolieren' verlangsamen jetzt alle von Euch getroffenen Ziele 6 Sek. lang um 60% und verringern 10 Sek. lang die von ihnen erhaltene Heilung um 50%." }
entries[424598] = { ["name"] = "Schwellendes Gewächs" }
entries[424599] = { ["name"] = "Gunst des Waldes", ["text"] = "100 Meter Reichweite\nKanalisiert (Wirken in 0 sek.)\nHeilt Ziele in der Nähe." }
entries[424600] = { ["name"] = "Giftiger Hieb", ["text"] = "Nahkampfreichweite\nWirken in 1 sek.\nBohrt die Waffe des Zaubernden in den Gegner und verursacht sofort Naturschaden sowie 12 Sek. lang alle 5.2 Sek. zusätzlichen Naturschaden." }
entries[424601] = { ["name"] = "Braunfelliger stachliger Bakar", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Was für ein guter Junge. Oder Mädchen. Ist manchmal schwer auszumachen, aber immer gut.\"\nHandelsposten" }
entries[424603] = { ["name"] = "Heureka!" }
entries[424605] = { ["name"] = "Wilde Wurzeln", ["text"] = "Sofort\nMacht das Ziel 4 Sek. lang bewegungsunfähig." }
entries[424607] = { ["name"] = "Taivan", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Ihr müsst nicht die Erwartungen der ganzen Welt erfüllen. Seid, wer Taivan weiß, was Ihr sein *könnt*.\"\nErfolg:\nEine erweckte Welt\nKategorie:\nErweiterungsfeatures" }
entries[424609] = { ["name"] = "Zeitschloss", ["text"] = "100 Meter Reichweite\nKanalisiert (Wirken in 0 sek.)\nFriert die Zeit für jene ein, die durch die Barriere gehen." }
entries[424612] = { ["name"] = "Blubberblasenblasrohr", ["text"] = "Animabonus\n20 Meter Reichweite\nSofort\nErlaubt Euch, Traumblasen aufzuheben und eine auf einen Gegner zu schleudern, um ihn durch die Luft fliegen zu lassen." }
entries[424613] = { ["name"] = "Mächtiges Schlaflied", ["text"] = "Animabonus\nSofort 20 sek. Abklingzeit\nErlaubt Euch, ein Schlaflied zu spielen, das Gegner in Schlaf versetzt." }
entries[424614] = { ["name"] = "Entkräftendes Gift", ["text"] = "Nahkampfreichweite\nWirken in 1 sek.\nBohrt die Waffe des Zaubernden in den Gegner und verursacht Naturschaden. Dieser Effekt verringert die Bewegungsgeschwindigkeit um 30% und verursacht alle 3 Sek. Naturschaden. Hält 12 Sek. lang an." }
entries[424615] = { ["name"] = "Feuereruption", ["text"] = "30 Meter Reichweite\nWirken in 2 sek. 3 sek. Abklingzeit\nInflicts 12 Fire damage to enemies within 3 yards of the impact.\nInflicts 2 Fire damage to all enemies within 3 yards of the impact every 2 sec for 10 Sek.." }
entries[424616] = { ["name"] = "Heiligung", ["text"] = "Sofort\n'Richturteil' gewährt einen Stapel 'Heiligung' und verringert den von Euch erlittenen Schaden um 2.0% pro Stapel. Bei 5 Stapeln wird Euer nächster Einsatz von 'Weihe' ermächtigt, wodurch Schaden und Heilung um 200% und der Radius um 30% erhöht werden. Die Stapel von 'Heiligung' werden zurückgesetzt, wenn die ermächtigte 'Weihe' endet." }
entries[424617] = { ["name"] = "Sternenschauer", ["text"] = "Animabonus\nSofort\nCa. 4 Procs pro Minute\nWenn Ihr Schaden erleidet, besteht eine Chance, dass um Euch herum Sterne vom Himmel niederregnen, die Gegnern im Bereich ihrer Landung 1 Min. lang pro Sekunde Schaden zufügen.\n(30s Abklingzeit)" }
entries[424618] = { ["name"] = "Blumenspur", ["text"] = "20 Meter Reichweite\nSofort\nBeschwört bei Vorwärtsbewegung ab und zu eine heilende Blume.\nBeschwört bei Rückwärtsbewegung ab und zu einen Giftpilz." }
