entries[424622] = { ["name"] = "Heiligung", ["text"] = "Sofort\n'Richturteil' gewährt einen Stapel 'Heiligung' und verringert den von Euch erlittenen Schaden um 2.0% pro Stapel. Bei 5 Stapeln wird Euer nächster Einsatz von 'Weihe' ermächtigt, wodurch Schaden und Heilung um 200% und der Radius um 30% erhöht werden. Die Stapel von 'Heiligung' werden zurückgesetzt, wenn die ermächtigte 'Weihe' endet.\n(Procchance: 50%)" }
