entries[424642] = { ["name"] = "Verlangsamter Sprung im PvP", ["text"] = "20 Meter Reichweite\nSofort\nSpringt in die Luft, um auf den Zielort herabzuschmettern, was allen Gegnern innerhalb von 10 Metern um den Einschlag körperlichen Schaden zufügt und sie mit ' Zerquetscht ' belegt." }
entries[424646] = { ["name"] = "Brennende Klauen", ["text"] = "10 Meter Reichweite\nWirken in 1.5 sek.\nFügt dem aktuellen Ziel 834022 Feuerschaden zu und lässt es 15 Sek. lang 50% mehr Schaden erleiden." }
