entries[424665] = { ["name"] = "Saat der Flamme", ["text"] = "Unbegrenzte Reichweite\nSofort\nSaaten der Flamme, die nicht von einem Spielercharakter zerquetscht werden, sind nach 5 Sek. ein ' Flammender Baum '.\n\nWenn ein Spielercharakter auf eine ' Saat der Flamme ' tritt, wird diese zerstört und der Spielercharakter erleidet 54393 Feuerschaden. Dieser Effekt erhöht den durch ' Saat der Flamme ' erlittenen Schaden 6 Sek. lang um 50% und ist stapelbar." }
