entries[424694] = { ["name"] = "Serevitlieferungen", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nErweckte Erde , Erwecktes Feuer\nZum Glück ist Serevit auf den Dracheninseln so häufig. Ein Großteil unserer Basisausrüstung besteht daraus! Bitte bringt uns 100 Stück Serevit und einige erweckte Elemente, wenn Ihr könnt.\n\nIhr erhaltet 1 Warenlieferung, die Ihr wöchentlich bei Eran'nda abgeben könnt, um die Traumwächter zu unterstützen." }
entries[424695] = { ["name"] = "Drakoniumlieferungen", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nErweckte Erde , Erwecktes Feuer\nWir brauchen Materialien, um Rüstungen und Waffen herzustellen. Bringt uns bitte 25 Stück Drakonium und eine kleine Sammlung erweckte Elemente.\n\nIhr erhaltet 1 Warenlieferung, die Ihr wöchentlich bei Eran'nda abgeben könnt, um die Traumwächter zu unterstützen." }
