entries[424731] = { ["name"] = "Kohlenpfanne der Auchenai", ["text"] = "Sofort\nMit dieser Kohlenpfanne könnt Ihr alle Gebetskerzen von Karabor gleichzeitig entzünden, die Kanalisierung dauert jedoch sehr lange.\n\nDas ist nicht notwendig, um diese Quest abzuschließen.\n\nWollt Ihr sie benutzen?" }
