entries[424734] = { ["name"] = "Entwurzelte Agonie", ["text"] = "300 Meter Reichweite\nSofort\nKnorrenwurzel ist durch Agonie bewegungsunfähig, erleidet 100% mehr Schaden und fügt allen Spielercharakteren 20 Sek. lang alle 1 Sek. 79776 Schattenflammenschaden zu.\n\nNach Ablauf erhält Knorrenwurzel eine Anwendung von ' Aufsteigende Manie '." }
entries[424736] = { ["name"] = "Balglieferungen", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nMakellose Protodrachenschuppe (15), Kristallrückenfell (15)\nLeder und Schuppen sind enorm vielseitige Materialien und wir nutzen sie für alle möglichen Waren und Ausrüstungsgegenstände. Falls Ihr welche habt, wir könnten 100 Stück widerstandsfähiges Leder oder Adamantschuppen brauchen, zusammen mit einigen Tiermaterialien.\n\nIhr erhaltet 1 Warenlieferung, die Ihr wöchentlich bei Eran'nda abgeben könnt, um die Traumwächter zu unterstützen." }
entries[424737] = { ["name"] = "Chaotische Verderbnis", ["text"] = "Wirken in 2 sek.\nSturmwache Gorren erfüllt einen Spielercharakter mit 4 Leerenaufladungen, die 5 Sek. lang alle 1 Sek. 848557 Schattenschaden verursachen.\n\nBei Entfernen wird eine Leerenaufladung aufgebraucht und diese Energie auf den nächsten Spielercharakter übertragen." }
entries[424738] = { ["name"] = "Infektiöse Sporen", ["text"] = "60 Meter Reichweite\nSofort\nDer Zaubernde schleudert einen fauligen Pilz. Getroffene Spielercharaktere werden für 3 Min. mit Sporen infiziert, woraufhin sie zufällig husten und dadurch für 1 Sek. betäubt werden." }
entries[424739] = { ["name"] = "Chaotische Verderbnis", ["text"] = "Unbegrenzte Reichweite\nSofort\nSturmwache Gorren erfüllt einen Spielercharakter mit 4 Leerenaufladungen, die 5 Sek. lang alle 1 Sek. 848557 Schattenschaden verursachen.\n\nBei Entfernen wird eine Leerenaufladung aufgebraucht und diese Energie auf den nächsten Spielercharakter übertragen." }
