entries[424742] = { ["name"] = "Schlachtfeldkommandant", ["text"] = "Eure Rufe und Schreie haben zusätzliche Effekte.\nSchlachtruf :\nErhöht die Ausdauer um 3%.\nDurchdringendes Heulen :\nRadius wird um 50% erhöht.\nBerserkerschrei :\nReichweite um 8 Meter erhöht.\nDrohruf :\nAbklingzeit um 15 Sek. verringert.\nAnspornender Schrei :\nEntfernt bewegungseinschränkende Effekte und erhöht die Bewegungsgeschwindigkeit von Verbündeten um 30%.\nDonnerndes Gebrüll :\nZiele erleiden 5% mehr Schaden aus allen Quellen, während sie bluten." }
entries[424743] = { ["name"] = "Kampferfahrung", ["text"] = "Sofort\nKerzenknappen erhalten 10% erhöhten körperlichen Schaden, der alle 15 Sek. gestapelt wird, solange sie im Kampf bleiben." }
