entries[424821] = { ["name"] = "Kollision bei hoher Geschwindigkeit", ["text"] = "Unbegrenzte Reichweite\nSofort\nDie Minenlore rammt alles, was sich in ihrer Bahn befindet, stößt es zurück und fügt allen getroffenen Spielercharakteren 8485573 körperlichen Schaden zu.\n\nTödlich für Schuftknechte und Schuftmägde." }
entries[424822] = { ["name"] = "Wilder Überschuss", ["text"] = "Animabonus\nSofort\nPro 200 verdienter Blüte beschwört Ihr eine mächtige Kreatur, die beim Tod mehr Blüte gewährt." }
entries[424823] = { ["name"] = "Nahrungslieferungen", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nGeripptes Muschelfleisch (15), Basiliskeneier (15), Brüffelchspannrippe (15), Mächtige Mammutrippen (15), Herzhafte Bärenkeule (15)\nDie grünen Traumwächter brauchen Nahrung! Unbedingt! Wir könnten 50 von den Fischen der Dracheninseln als Ergänzung zum Fleisch brauchen, um Mahlzeiten zuzubereiten. Wenn sie sich gestärkt haben, können wir es mit Fyrakks Truppen aufnehmen.\n\nIhr erhaltet 1 Warenlieferung, die Ihr wöchentlich bei Eran'nda abgeben könnt, um die Traumwächter zu unterstützen." }
