entries[424845] = { ["name"] = "Haltespulenbindung", ["text"] = "30 Meter Reichweite\nKanalisiert (Wirken in 0 sek.) 5 sek. Abklingzeit\nBelegt Euch selbst mit 'Haltespulenentzug', indem Ihr Euch an eine beliebige seltene Kreatur im Smaragdgrünen Traum bindet.\n\nSeltene Kreaturen zu besiegen, während 'Haltespulenentzug' aktiv ist, gewährt 'Straffe Haltespule'." }
entries[424846] = { ["name"] = "Traumfresser", ["text"] = "6 Meter Reichweite\nSofort 1 min Abklingzeit\nSchneidet ein Stück aus den Träumen Eures Ziels heraus und zehrt es auf, um einen Bonus zu erhalten, der von der Art der Kreatur abhängt." }
entries[424847] = { ["name"] = "Visionen des Jenseits", ["text"] = "100 Meter Reichweite\nSofort\nWenn Ihr Magieschaden erleidet, heilt Ihr um 1% Eurer gesamten Gesundheit. Dieser Effekt kann nicht öfter als einmal alle 30 Sek. auftreten. Der durch Entartungen erlittene Schaden ist um 5% erhöht.\n(30s Abklingzeit)" }
entries[424848] = { ["name"] = "Wildeste Träume", ["text"] = "Sofort\nVerringert den Fallschaden stark. Während Eure Gesundheit unter 50% liegt, ist Euer 'Lebensraub' um 10% erhöht." }
entries[424849] = { ["name"] = "Dämonischer Schrecken", ["text"] = "Sofort\nVerringert den erlittenen Schattenschaden um 6%, erhöht den erlittenen körperlichen Schaden um 6% und den erlittenen Heiligschaden um 6%." }
entries[424850] = { ["name"] = "Verheerende Träume", ["text"] = "Sofort 1 min Abklingzeit\nErhöht die Reit- und Bewegungsgeschwindigkeit um 5%. Auf Kontinenten, die Ihr vollständig erkundet habt, verdoppelt sich die Geschwindigkeit." }
