entries[424876] = { ["name"] = "Khaz'goritlieferungen", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nErweckte Erde , Erwecktes Feuer\nKhaz'gorit ist ein seltenes Metall, dass wir für unsere mächtigste Ausrüstung verwenden. Bitte bringt uns 15 Einheiten davon sowie eine kleine Sammlung erweckte Elemente.\n\nIhr erhaltet 1 Warenlieferung, die Ihr wöchentlich bei Eran'nda abgeben könnt, um die Traumwächter zu unterstützen." }
