entries[424879] = { ["name"] = "Erdzerschmetterer", ["text"] = "Wirken in 4 sek.\nI.N.G.A. schmettert auf den Boden, wodurch sie allen Spielercharakteren 3636674 Naturschaden zufügt und seismische Impulse auslöst, die alle instabilen Stacheln zerstören." }
