entries[424881] = { ["name"] = "Tierhautlieferungen", ["text"] = "Wirken in 1.5 sek.\nReagenzien:\nFeuererfüllter Balg (10), Makelloses Vorquinhorn (5)\nTierhäute helfen, die Haltbarkeit unserer Leder- und Kettenrüstung zu verbessern. Bitte bringt uns 15 dichte Bälge oder schimmernde Schuppenbälge sowie einige Tierartmaterialien.\n\nIhr erhaltet 1 Warenlieferung, die Ihr wöchentlich bei Eran'nda abgeben könnt, um die Traumwächter zu unterstützen." }
