entries[424888] = { ["name"] = "Seismisches Schmettern", ["text"] = "100 Meter Reichweite\nWirken in 4 sek.\nI.N.G.A. schlägt mit ungeheurer Kraft auf das aktuelle Ziel ein, fügt ihm 36366741 körperlichen Schaden zu und belegt es mit ' Seismischer Nachhall '." }
entries[424889] = { ["name"] = "Seismischer Nachhall", ["text"] = "Unbegrenzte Reichweite\nSofort\nWellen der Kraft umgeben das Ziel und fügen ihm 30 Sek. lang alle 3 Sek. 1212225 Naturschaden zu.\n\nWenn sie gebannt werden, wird das Ziel von ' Steinschild ' durchdrungen." }
