entries[424891] = { ["name"] = "Rankenspeer", ["text"] = "100 Meter Reichweite\nWirken in 4 sek.\nDer Zaubernde schleudert einen Speer in einer geraden Linie, der alle getroffenen Gegner aufspießt und 1045599 körperlichen Schaden verursacht. Nach 3 Sek. Sek. werden diese Ziele zum Zaubernden gezogen." }
