entries[425037] = { ["name"] = "Lavaodem", ["text"] = "30 Meter Reichweite\nWirken in 4 sek.\nDie Kreatur atmet sengende Lava aus, fügt Spielercharakteren in einem kegelförmigen Bereich vor sich 652713 Feuerschaden zu und desorientiert sie für 5 Sek." }
