entries[425042] = { ["name"] = "Sporenwelle", ["text"] = "Wirken in 1.5 sek.\nDer Zaubernde schleudert einen fauligen Pilz. Getroffene Spielercharaktere werden für 3 Min. mit Sporen infiziert, woraufhin sie zufällig husten und dadurch für 1 Sek. betäubt werden." }
