entries[425048] = { ["name"] = "Dunkle Gravitation", ["text"] = "Wirken in 2 sek.\nSturmwache Gorren kanalisiert Umbralenergie, wodurch er Spielercharaktere zu sich zieht und ihnen 4 Sek. lang alle 2 Sek. 727335 Schattenschaden zufügt.\n\nWenn die Kanalisierung abgeschlossen wurde, explodiert Gorrens Hammer vor Energie, trifft dabei Spielercharaktere innerhalb von 8 Metern, fügt ihnen 16971146 Schattenschaden zu und stößt sie weg." }
entries[425049] = { ["name"] = "Velens Zuflucht", ["text"] = "Sofort\nHeals the caster for 1% of maximum health every 1 sec for bis Abbruch." }
