entries[425112] = { ["name"] = "Tollkühner Ansturm", ["text"] = "Unbegrenzte Reichweite\nSofort\nDer alte Wachsbart befiehlt Docht, auf den am weitesten entfernten Spielercharakter zuzustürmen. Dieser Angriff stößt alles in seinem Weg zurück, fügt allen Spielercharakteren 6061123 körperlichen Schaden zu und löst am Ende des Ansturms einen ' Einsturz ' aus.\n\nTödlich für Schuftknechte und Schuftmägde." }
entries[425113] = { ["name"] = "Realität zermalmen", ["text"] = "Unbegrenzte Reichweite\nSofort\nSturmwache Gorren lädt seinen Hammer mit Leerenenergie auf und springt zur Position des Spielercharakters, wobei er allen Spielercharakteren 3636674 Schattenschaden zufügt.\n\nDieser Einschlag erzeugt mehrere Instanzen von ' Realitätsriss ' und hinterlässt eine Lache von ' Siechende Leere '." }
