entries[425416] = { ["name"] = "Kriecherdrache des tiefgrünen Gladiators", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Dieser Drache besuchte viele Helden in ihren Träumen, bevor er sich Eurer Sache anschloss.\"\nErfolg:\nGladiator: Saison 3 von Dragonflight\nKategorie:\nSpieler gegen Spieler" }
entries[425417] = { ["name"] = "Solarmahlstrom", ["text"] = "Sofort\nEntfesselt einen Solarmahlstrom, der Euch und Gegner in der Nähe verlangsamt, bevor er nach 2 Sek. in Flammen ausbricht. Gegner erleiden im Verlauf von 12 Sek. 9449 Feuerschaden und Ihr 4725 Feuerschaden.\n\nKann aus der Bewegung heraus gewirkt werden. Der Schaden erhöht sich mit jedem getroffenen Gegner, bis zu einem Maximum von 5." }
entries[425420] = { ["name"] = "Harzbeschichtung", ["text"] = "50 Meter Reichweite\nWirken in 2 sek.\nBeschichtet einen besudelten Peitscher in der Nähe mit gehärtetem Harz und verringert dessen erlittenen Schaden um 50%.\n\nDieser Effekt hält an, bis der Zaubernde stirbt." }
